import { BlankPage } from "./BlankPage";
import { CoverWrapper } from "./covers/CoverWrapper";
import { GreetingPage } from "./GreetingPage";
import { WordCloudPage } from "./WordCloudPage";
import type { AlbumConfig, AlbumSlide } from "./types";

export interface SlideSurfaceProps {
  album: AlbumConfig;
  slide: AlbumSlide;
  /** Let a greeting grow past the page instead of shrinking to fit it. */
  fitToPage?: boolean;
}

/**
 * Turns one slide into its surface.
 *
 * Every view goes through here — the book, the carousel, the printed sheet —
 * so paper matches screen and a new kind of slide cannot be taught to one
 * renderer and forgotten in the others.
 */
export function SlideSurface({ album, slide, fitToPage }: SlideSurfaceProps) {
  switch (slide.kind) {
    case "page":
      return (
        <GreetingPage
          album={album}
          page={slide.page}
          part={slide.part}
          fitToPage={fitToPage}
        />
      );
    case "word-cloud":
      return <WordCloudPage album={album} />;
    case "blank":
      return <BlankPage album={album} />;
    default:
      return (
        <CoverWrapper
          album={album}
          face={slide.kind === "front-cover" ? "front" : "back"}
        />
      );
  }
}
